(()=>{'use strict';
const CFG=window.PANAGSANGKA_CONFIG||{},API=(CFG.API_BASE_URL||'https://panagsangka.mdmsportal.uk').replace(/\/$/,'');
const $=(id)=>document.getElementById(id);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const grades=[7,8,9,10,11,12];const ICONS={dashboard:'🏠',events:'🗂️',encode:'✍️',ranking:'🏆',approvals:'✅',users:'👥',settings:'⚙️',reports:'📑',history:'📜',login:'🔑',logout:'🚪',my:'🎯',judging:'⚖️','judging-my':'📝'};
const LABELS={judging:['Digital Judging','Configure official judges, criteria and contest tabulation'],'judging-my':['My Judging','Only your officially assigned judging contests'],dashboard:['Live Dashboard','Live tally and overall ranking of intramural events'],events:['Manage Events','General events, specific events, and sub-events'],encode:['Encode Placements','Official event placements and automated points'],ranking:['Overall Rankings','Official grade-level championship standings'],approvals:['Result Verification','Review and approve submitted placements'],users:['Event Managers','User accounts and event-based assignments'],settings:['Branding & Settings','School identity and official grade-level logos'],reports:['Official Reports','Approved tally breakdown and records'],history:['Championship History','Official past and present intramurals rankings'],my:['My Assigned Events','Only events officially assigned to your account']};
const state={judgingAdmin:null,judgeEvents:[],token:localStorage.getItem('panag_auth')||'',user:null,events:[],users:[],results:[],corrections:[],public:null,history:null,historyDetail:null,historySelected:null,page:'dashboard',expanded:new Set(),currentEvent:null,online:false,refreshing:false,initialized:false,socket:null,toastTimer:null};
const imageUrl=p=>p&&typeof p==='string'&&/^\/assets\/[a-z0-9._-]+\.webp$/i.test(p)?API+p:'';
function logo(g,large=false){const rec=state.public?.branding?.grades?.find(x=>Number(x.grade)===Number(g));const src=imageUrl(large?rec?.logo_path:(rec?.logo_thumb||rec?.logo_path));return src?`<img class="grade-logo g${g}" loading="lazy" src="${esc(src)}" alt="Grade ${g} official logo">`:`<span class="grade-logo g${g}" title="Grade ${g}">${g}</span>`;}
function badge(s){return `<span class="status-badge ${esc(s||'draft')}">${esc(s||'Pending')}</span>`;}
function btn(label,action,id='',variant='',more=''){return `<button type="button" class="action-button ${variant}" data-action="${esc(action)}" ${id!==''?`data-id="${esc(id)}"`:''} ${more}>${label}</button>`;}
function flash(message,type='good'){const el=$('toast');el.textContent=message;el.className='toast '+type;clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.add('hidden'),4300);}
async function api(path,opts={}){const headers={'Content-Type':'application/json'};if(state.token)headers.Authorization='Bearer '+state.token;let response;try{response=await fetch(API+path,{...opts,headers:{...headers,...opts.headers},cache:'no-store'});}catch(err){state.online=false;onlineStatus();throw Error('Network/CORS connection failed on '+(opts.method||'GET')+' '+path+'. Check API health, Cloudflare tunnel and backend CORS (PUT must be allowed).');}let data=null;try{data=await response.json();}catch{}if(!response.ok){if(response.status===401&&state.user){state.user=null;state.token='';localStorage.removeItem('panag_auth');flash('Session expired. Please log in again.','bad');}throw Error(data?.error||`Request failed (${response.status})`);}state.online=true;onlineStatus();return data;}
function onlineStatus(){const el=$('online-dot');el.className='connection-pill '+(state.online?'connected':'offline');el.innerHTML=`<i></i><span>${state.online?'Live Connected':'Backend Offline'}</span>`;}
const POST=(url,obj)=>api(url,{method:'POST',body:JSON.stringify(obj)}),PUT=(url,obj)=>api(url,{method:'PUT',body:JSON.stringify(obj)}),PATCH=(url,obj)=>api(url,{method:'PATCH',body:JSON.stringify(obj)});
function navItems(){if(state.user?.role==='admin')return [['dashboard','Dashboard'],['events','Manage Events'],['judging','Digital Judging'],['approvals','Verify Results'],['ranking','Overall Ranking'],['users','Event Managers'],['reports','Reports'],['history','History'],['settings','Settings']];if(state.user?.role==='judge')return [['judging-my','My Judging'],['ranking','Overall Ranking'],['history','History']];if(state.user?.role==='manager')return [['my','My Events'],['ranking','Overall Ranking'],['history','History']];return [['dashboard','Live Dashboard'],['ranking','Overall Ranking'],['history','History']];}
function nav(){const menu=navItems();$('side-navigation').innerHTML=menu.map(([id,name])=>`<button class="nav-item ${state.page===id?'active':''}" data-action="page" data-id="${id}"><span class="nav-ico">${ICONS[id]}</span><span>${esc(name)}</span></button>`).join('');$('mobile-nav').innerHTML=(menu.length>5?menu.slice(0,4):menu).map(([id,name])=>`<button data-action="page" data-id="${id}" class="${state.page===id?'active':''}"><span class="nav-ico">${ICONS[id]}</span><span>${esc(name.replace('Overall Ranking','Rankings').replace('Manage Events','Events'))}</span></button>`).join('')+(menu.length>5?`<button data-action="more" class="${menu.slice(4).some(([id])=>id===state.page)?'active':''}"><span class="nav-ico">☰</span><span>More</span></button>`:'');$('profile-button').innerHTML=`👤 <span>${esc(state.user?.name||'Login')}</span>`;const [name,desc]=LABELS[state.page]||LABELS.dashboard;$('page-title').textContent=name;$('page-description').textContent=desc;$('heading-icon').textContent=ICONS[state.page]||'🏅';}
function render(){nav();const p=state.page;let html='';switch(p){case 'dashboard':html=dashboard();break;case 'ranking':html=rankingPage();break;case 'events':html=state.user?.role==='admin'?manageEvents():denied();break;case 'my':html=state.user?.role==='manager'?myEvents():denied();break;case 'judging':html=state.user?.role==='admin'?judgingUI.admin():denied();break;case 'judging-my':html=state.user?.role==='judge'?judgingUI.judgeHome():denied();break;case 'approvals':html=state.user?.role==='admin'?approvalsPage():denied();break;case 'users':html=state.user?.role==='admin'?usersPage():denied();break;case 'settings':html=state.user?.role==='admin'?settingsPage():denied();break;case 'reports':html=state.user?.role==='admin'?reportsPage():denied();break;case 'history':html=PanagSeasonsUI.history(state,esc,btn,imageUrl);break;default:html=dashboard();} $('main-content').innerHTML=html;updateHeroLogo();}
const judgingUI=window.PanagJudgingUI.create({state,api,POST,PUT,PATCH,esc,btn,modal,closeModal,flash,loadAll,grades,logo});
function denied(){return '<div class="callout warning">This area is restricted to authorized users.</div>';}
function updateHeroLogo(){const b=state.public?.branding||{};
 $('hero-school-logo').innerHTML=imageUrl(b.school_logo)?`<img src="${esc(imageUrl(b.school_logo))}" alt="Official school logo">`:'<span>🔥</span>';
 document.querySelector('.hero-overline').textContent=b.school_name||'MAGALLANES NATIONAL HIGH SCHOOL';
 const h=document.querySelector('.hero-center h1');h.replaceChildren(document.createTextNode((b.event_name||'PANAGSANGKA')+' '));const year=document.createElement('span');year.textContent=b.year||2026;h.appendChild(year);
 document.querySelector('.hero-subtitle').textContent=b.subtitle??'LIVE TALLY & OVERALL RANKING SYSTEM';
 document.querySelector('.hero-tagline').textContent=b.tagline??'ONE SCHOOL • ONE SPIRIT • HIGHER TOGETHER';
 document.querySelector('.side-brand strong').textContent=(b.event_name||'PANAGSANGKA')+' '+(b.year||2026);
 document.querySelector('.side-brand span').textContent=b.sidebar_subtitle??'Official Live Tally System';
 const w=document.querySelector('.side-bottom-art');w.querySelectorAll(':scope > span').forEach(x=>x.remove());
 for(const item of String(b.sidebar_words??'SPORTS\nCULTURE\nTALENT\nUNITY').split(/[\n•]+/).map(x=>x.trim()).filter(Boolean)) {const el=document.createElement('span');el.textContent=item;w.insertBefore(el,w.querySelector('.mini-flame'));}
 document.querySelector('.hero-left').textContent=b.decoration_left??'ONE SCHOOL • ONE SPIRIT';
 document.querySelector('.hero-right').textContent=b.decoration_right??'SPORTS • CULTURE • TALENT • UNITY';
 document.querySelector('.page-footer').textContent=(b.event_name||'PANAGSANGKA')+' '+(b.year||2026)+'  •  '+(b.footer??'OFFICIAL LIVE TALLY • MANILA TIME');
 document.title=(b.event_name||'PANAGSANGKA')+' '+(b.year||2026)+' | Live Tally';
}
function statCard(color,icon,n,title,subtitle){return `<div class="stat-card ${color}"><div class="stat-icon">${icon}</div><div><strong>${esc(n)}</strong><div class="stat-title">${esc(title)}</div><small>${esc(subtitle)}</small></div></div>`;}
function rankingTable(rows){return `<div class="table-wrap"><table class="ranking-table"><thead><tr><th>Rank</th><th>Grade Level</th><th>Total Points</th><th>Events</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="${r.rank===1?'rank-gold':r.rank===2?'rank-silver':r.rank===3?'rank-bronze':''}">${r.rank===1?'🥇':r.rank===2?'🥈':r.rank===3?'🥉':esc(r.rank)} <span class="tiny">${r.rank<=3?['','1st','2nd','3rd'][r.rank]:''}</span></td><td><div class="grade-cell">${logo(r.grade)}<span>Grade ${r.grade}</span></div></td><td><span class="points-val">${Number(r.points)||0}</span></td><td>${Number(r.approved_events)||0}</td></tr>`).join('')}</tbody></table></div>`;}
function rulesCards(){const rules=[['saludo','🎭','SALUDO CONTEST'],['emblem','🎨','BEST EMBLEM '+(state.public?.branding?.year||2026)],['singing','🎵','SINGING DUET'],['sports','⚽','SPORTS GAMES']];const ref={saludo:[['Champion',20],['1st Runner-up',15],['2nd Runner-up',10],['Participation',5]],emblem:[['Mr. and Ms. Sports',20],['1st Runner-up',15],['2nd Runner-up',10],['Participation',5]],singing:[['Champion',6],['1st Runner-up',5],['2nd Runner-up',4],['3rd Runner-up',3],['4th Runner-up',2],['5th Runner-up',1],['No Participation',0]],sports:[['Champion',6],['1st Runner-up',5],['2nd Runner-up',4],['3rd Runner-up',3],['4th Runner-up',2],['5th Runner-up',1],['No Participation',0]]};return `<div class="points-categories">${rules.map(([key,icon,name])=>`<div class="rule-card ${key}"><h4><span>${icon}</span>${name}</h4><table>${ref[key].map(([rank,points])=>`<tr><td>${esc(rank)}</td><td>${points}</td></tr>`).join('')}</table></div>`).join('')}</div>`;}
function unavailable(){return `<div class="callout warning">Public live API not reachable. Start the Windows backend and its <b>panagsangka-api</b> Cloudflare tunnel. The interface will synchronize automatically once connected.<br><span class="tiny">API: ${esc(API)}</span></div>`;}
function dashboard(){const p=state.public;if(!p)return `${unavailable()}<div class="tally-banner"><div><div class="section-overline">${esc((state.public?.branding?.event_name||'PANAGSANGKA')+' '+(state.public?.branding?.year||2026))}</div><h3>Official Live Tally</h3></div><div class="trophy-emoji">🏆</div></div>`;
return `<section class="stats-grid">${statCard('', '🏆',p.stats.categories,'EVENT CATEGORIES','Official point systems')}${statCard('green','👥',6,'GRADE LEVELS','Grade 7 – Grade 12')}${statCard('orange','🏅',p.stats.events,'TOTAL EVENTS','Scoring events & sub-events')}${statCard('purple','📊',p.stats.approved,'APPROVED RESULTS','Official standings updated')}</section>
<div class="dashboard-grid"><section class="panel panel-pad"><div class="panel-title-row"><h3 class="panel-title">🏆 Overall Ranking <span class="muted tiny">(Live)</span></h3>${btn('View Rankings →','page','ranking','smallbtn')}</div>${rankingTable(p.standings)}</section><section class="panel panel-pad"><div class="panel-title-row"><h3 class="panel-title">📋 Official Points Reference</h3><span class="status-badge approved">${esc(p.branding.year)} Rules</span></div>${rulesCards()}</section></div><div style="margin-top:13px" class="tally-banner"><div><div class="section-overline">${esc(p.branding.banner_kicker)}</div><h3>${esc(p.branding.banner_motto)}</h3><div class="muted small">${esc(p.branding.banner_detail)}</div></div><div class="trophy-emoji">🏆</div></div>`;}
function rankingPage(){if(!state.public)return unavailable();const p=state.public;return `<div class="tally-banner"><div><div class="section-overline">OFFICIAL LIVE RANKING</div><h3>🏆 Overall Championship Standings</h3><div class="muted small">Grade logos and rankings update after administrator approval.</div></div><div class="trophy-emoji">🏆</div></div><div class="panel panel-pad"><div class="panel-title-row"><h3 class="panel-title">🏅 Grade 7 – Grade 12</h3><span class="status-badge approved">${p.stats.approved} Results Approved</span></div>${rankingTable(p.standings)}</div><div class="grade-hero-list">${p.standings.map(r=>`<div class="grade-hero-card">${logo(r.grade,true)}<strong>Grade ${r.grade}</strong><span class="small muted">Rank #${r.rank}</span><div><em>${r.points}</em> <span class="tiny muted">pts</span></div></div>`).join('')}</div><div class="panel panel-pad"><h3 class="panel-title" style="margin-bottom:12px">Approved Event Results</h3>${p.approved_results.length?`<div class="table-wrap"><table class="report-table"><tr><th>Event</th><th>Champion / Top Award</th><th>Approved</th></tr>${p.approved_results.map(x=>`<tr><td>${esc(x.event_name)}</td><td>${esc((Object.entries(x.entries).find(([g,rank])=>rank==='champion')||['—'])[0] !== '—'?'Grade '+Object.entries(x.entries).find(([g,rank])=>rank==='champion')[0]:'—')}</td><td>${esc(x.approved_at||'')}</td></tr>`).join('')}</table></div>`:'<p class="empty-notice">No official results approved yet.</p>'}</div>`;}
const naturalCollator=new Intl.Collator('en',{numeric:true,sensitivity:'base'});
const eventLabel=e=>e?.display_name||((e?.path||'').split(' → ').filter((v,i)=>!(i===0&&v==='SPORTS GAMES')).join(' – '))||e?.name||'';
const naturalEvents=(a,b)=>naturalCollator.compare(a?.path||eventLabel(a),b?.path||eventLabel(b));
function descendants(parent){return state.events.filter(e=>e.parent_id===parent&&e.id!==parent).sort(naturalEvents);}
function getEvent(id){return state.events.find(e=>e.id===Number(id));}
function trail(e){let bits=[],n=e,i=0;while(n&&i++<30){bits.unshift(n.name);n=getEvent(n.parent_id);}return bits.join(' › ');}
function treeNode(e,depth=0){const children=descendants(e.id),open=state.expanded.has(e.id);const ico=depth===0?'🏆':depth===1?'🏃':'🏅';return `<div class="tree-block"><div class="tree-row depth-${Math.min(depth,2)}"><button class="tree-main" data-action="toggle-tree" data-id="${e.id}" title="Expand event"><span>${children.length?(open?'▾':'▸'):'•'}</span><span>${ico}</span><span>${esc(e.name)}</span></button>${children.length?`<span class="tree-count">${children.length} nested events · Group only</span>`:e.is_scoring_event?badge(e.result?.status||'pending'):'<span class="tree-count">Group only</span>'}<div class="tree-actions">${btn('+','new-child',e.id,'smallbtn iconbtn','aria-label="Add sub-event"')}${btn('✎','edit-event',e.id,'secondary smallbtn iconbtn','aria-label="Rename event"')}${btn('🗑','delete-event',e.id,'danger smallbtn iconbtn','aria-label="Delete or archive event"')}</div></div>${children.length&&open?`<div class="tree-children">${children.map(ch=>treeNode(ch,depth+1)).join('')}</div>`:''}</div>`;}
function manageEvents(){return `<div class="section-row"><div><h3 class="section-title">Event Hierarchy</h3><p class="muted small">General event → Specific sport → Sub-event. Use + to add, ✎ to rename, and 🗑 to delete/archive.</p></div><div class="actions">${btn('+ Add General Event','new-root','','') }</div></div><div class="panel panel-pad"><div class="panel-title-row"><h3 class="panel-title">🗂️ Official Event Structure</h3><span class="muted small">${state.events.filter(e=>e.is_scoring_event).length} scoring events · ${state.events.length} hierarchy entries</span></div><div class="events-tree">${state.events.filter(e=>e.parent_id===null).map(e=>treeNode(e)).join('')}</div></div><div class="callout">Scoring happens only at the lowest-level event. A parent sport automatically rolls up approved points from its sub-events; no double counting. Events with recorded results are archived rather than erased.</div>`;}
function myEvents(){const leaves=state.events.filter(e=>e.is_scoring_event).sort(naturalEvents);const groups=new Map();for(const e of leaves){const t=(e.path||'').split(' → ');const group=t[0]==='SPORTS GAMES'?(t[1]||'Sports Games'):(t[0]||'Other Contests');if(!groups.has(group))groups.set(group,[]);groups.get(group).push(e);}return `<div class="tally-banner"><div><div class="section-overline">EVENT MANAGER PORTAL</div><h3>My Assigned Events</h3><div class="muted small">Only your assigned events can be viewed or encoded.</div></div><div class="trophy-emoji">🎯</div></div><div class="section-row"><h3 class="section-title">${leaves.length} Available Scoring Events</h3><span class="muted small">Submission requires Admin approval</span></div><div class="manager-event-groups">${Array.from(groups).sort(([a],[b])=>naturalCollator.compare(a,b)).map(([group,items])=>`<section class="manager-event-group"><div class="manager-group-heading">🏅 ${esc(group)} <span>${items.length} scoring events</span></div><div class="event-list">${items.map(e=>eventCard(e)).join('')}</div></section>`).join('')||'<div class="centered-empty">🔒<p>No events assigned yet. Ask the Admin to assign an event to your account.</p></div>'}</div>`;}
function eventCard(e){const s=e.result?.status||'pending';return `<div class="event-card"><div class="event-meta"><div class="event-icon">${e.rule==='sports'?'🏃':e.rule==='singing'?'🎵':e.rule==='saludo'?'🎭':'🎨'}</div><div style="min-width:0;flex:1"><h3>${esc(eventLabel(e))}</h3><p>${esc(e.path||trail(e))}</p></div>${badge(s)}</div><div class="event-card-footer"><span class="muted tiny">${s==='approved'?'Official • Locked':s==='submitted'?'Awaiting Admin verification':'Placement entry'}</span>${e.judging_enabled?`<button type="button" class="action-button smallbtn" data-j-action="manager-judging" data-j-id="${e.id}">⚖ Review Judging →</button>`:btn(s==='approved'||s==='submitted'?'View Results →':'Encode Placements →','encode',e.id,'smallbtn')}</div></div>`;}
function approvalsPage(){const results=state.results.filter(x=>['submitted','returned'].includes(x.status));const requests=state.corrections.filter(x=>x.status==='pending').sort(naturalEvents);return `<div class="section-row"><div><h3 class="section-title">Verification Queue</h3><p class="muted small">Admin approval is required before points appear on the live leaderboard.</p></div>${badge((results.length+requests.length)+' awaiting review')}</div>${requests.length?`<div class="panel panel-pad" style="margin-bottom:13px"><h3 class="panel-title">✎ Approved Score Corrections (${requests.length})</h3><p class="muted small">Previously approved standings remain unchanged until you accept a correction.</p>${requests.map(r=>`<div class="approval-card"><div class="section-row"><h4>${esc(r.event_name)}</h4>${badge('submitted')}</div><p class="small">Requested by ${esc(r.manager_name||'Event Manager')} · ${esc(r.created_at)}</p><p class="callout warning">${esc(r.reason)}</p><div class="approval-actions">${btn('Compare & Decide','review-correction',r.id)}</div></div>`).join('')}</div>`:''}<div class="panel panel-pad">${results.length?results.map(r=>`<div class="approval-card"><div class="section-row"><div><h4>${esc(r.event_name)}</h4><span class="muted tiny">${esc(r.updated_at)}</span></div>${badge(r.status)}</div><div class="muted small">${grades.map(g=>`G${g}: ${esc(r.entries[g]||'—')}`).join(' · ')}</div>${r.comment?`<p class="callout warning">Previous note: ${esc(r.comment)}</p>`:''}${r.status==='submitted'?`<div class="approval-actions">${btn('View Breakdown','review',r.event_id,'secondary smallbtn')}${btn('↩ Return','return',r.event_id,'danger smallbtn')}${btn('✓ Approve Official Result','approve',r.event_id,'smallbtn')}</div>`:''}</div>`).join(''):'<div class="centered-empty">✅<p>No results awaiting verification.</p></div>'}</div>`;}
function usersPage(){return `<div class="section-row"><div><h3 class="section-title">Accounts & Event-Based Access</h3><p class="muted small">Managers see only assigned events. A parent assignment includes all descendant sub-events.</p></div>${btn('+ Add Manager','add-user')}</div><div class="panel panel-pad">${state.users.map(u=>`<div class="manager-row"><div><strong>${esc(u.name)}</strong> ${badge(u.active?'approved':'returned')} <span class="muted tiny">${esc(u.role)}</span><div class="muted small">@${esc(u.username)} · ${u.role==='manager'?u.assignments.length+' saved assignments':'Full Admin access'}</div></div><div class="actions" style="display:flex;gap:5px;flex-wrap:wrap">${u.role==='manager'?btn('Assign','assign',u.id,'smallbtn'):''}${btn('Edit','edit-user',u.id,'secondary smallbtn')}</div></div>`).join('')||'<p class="empty-notice">No user accounts.</p>'}</div>`;}
function settingsPage(){const b=state.public?.branding||{grades:[]};return PanagSeasonsUI.settings(b,esc)+`<div class="section-row"><div><h3 class="section-title">Official School & Grade Logos</h3><p class="muted small">Optimized by the backend for fast PWA display, including original large uploads.</p></div></div><div class="panel panel-pad" style="margin-bottom:13px"><h3 class="panel-title" style="margin-bottom:13px">🏫 Official School Identity</h3><div class="field-group"><label class="field-label" for="school-name">Official School Name</label><input class="text-field" id="school-name" maxlength="120" value="${esc(b.school_name||'')}"/></div><div class="section-row"><div style="display:flex;align-items:center;gap:10px">${imageUrl(b.school_logo)?`<img class="setting-logo-preview" src="${esc(imageUrl(b.school_logo))}" alt="School logo"/>`:'<div class="setting-logo-preview" style="display:grid;place-items:center;font-size:40px">🏫</div>'}<div><strong>School Official Logo</strong><div class="input-help">PNG, JPEG, WebP or GIF · up to 24 MB before optimization</div></div></div><div class="actions"><label class="action-button secondary" style="display:inline-block" for="upload-school">Upload Logo</label><input id="upload-school" type="file" accept="image/png,image/jpeg,image/webp,image/gif" data-upload="school" hidden>${btn('Save School Name','save-school')}</div></div></div><div class="panel panel-pad"><h3 class="panel-title" style="margin-bottom:13px">🛡️ Official Grade Level Logos</h3><p class="muted small">Uploaded logos appear automatically in leaderboard tables, grade cards, and approved result views.</p><div class="logo-list">${grades.map(g=>{const src=imageUrl(b.grades?.find(x=>x.grade===g)?.logo_path);return `<div class="logo-upload-card"><div><span class="small" style="font-weight:850">Grade ${g}</span><div style="margin-top:10px">${src?`<img class="grade-logo" src="${esc(src)}" alt="Grade ${g} official logo">`:logo(g)}</div></div><label for="upload-g${g}">📤 Upload Logo</label><input id="upload-g${g}" data-upload="grade" data-grade="${g}" type="file" accept="image/png,image/jpeg,image/webp,image/gif"/></div>`;}).join('')}</div><div class="callout">Each upload produces a 512px WebP master and 144px WebP thumbnail. SQLite stores only file paths and metadata, not large original image blobs.</div></div>`;}
function reportsPage(){if(!state.public)return unavailable();const events=state.public.approved_results;return `<div class="section-row"><div><h3 class="section-title">Official Tally Report</h3><p class="muted small">Print leaderboard or export a CSV of officially approved totals.</p></div><div class="actions">${btn('🖨 Print Report','print','','secondary')}${btn('⬇ Export CSV','csv')}</div></div><div class="panel panel-pad"><h3 class="panel-title" style="margin-bottom:13px">Overall Championship Points</h3>${rankingTable(state.public.standings)}<p class="muted small">Generated on ${esc(new Date().toLocaleString('en-PH',{timeZone:'Asia/Manila'}))} (Asia/Manila)</p></div><div class="panel panel-pad" style="margin-top:13px"><h3 class="panel-title" style="margin-bottom:13px">Approved Events (${events.length})</h3>${events.length?`<div class="table-wrap"><table class="report-table"><tr><th>Event</th><th>Top Award Winner</th><th>Date Approved</th></tr>${events.slice().sort((a,b)=>naturalCollator.compare(a.event_name,b.event_name)).map(e=>{const winner=Object.entries(e.entries).find(([,r])=>r==='champion');return `<tr><td>${esc(e.event_name)}</td><td>${winner?'Grade '+esc(winner[0]):'—'}</td><td>${esc(e.approved_at)}</td></tr>`;}).join('')}</table></div>`:'<p class="empty-notice">No approved results yet.</p>'}</div><div class="panel panel-pad" style="margin-top:13px"><h3 class="panel-title">🗄️ Database Maintenance</h3><p class="muted small">Admin only. Backups are saved on your Windows PC and include optimized school/grade logo files. Always keep copies outside the PC.</p><div class="maintenance-actions">${btn('⬇ Create Backup','backup','','secondary')}${btn('♻ Restore Backup','open-restore','','secondary')}${btn('⚠ Reset Operational','open-reset','','danger')}</div><div class="callout">Reset clears drafts, submitted results, approved points and correction requests. It preserves all events, users, permissions, logos and scoring rules; an automatic pre-reset backup is created.</div></div>`;}
function modal(title,html,wide=false){$('modal-root').innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h3>${esc(title)}</h3><button class="modal-close" data-action="close-modal" aria-label="Close">✕</button></div><div class="modal-body">${html}</div></div></div>`;}
function closeModal(){$('modal-root').innerHTML='';}
function loginModal(){modal('🔐 Admin / Event Manager / Judge Login',`<form id="login-form"><div class="field-group"><label class="field-label" for="login-user">Username</label><input class="text-field" id="login-user" name="username" autocomplete="username" required></div><div class="field-group"><label class="field-label" for="login-password">Password</label><input class="text-field" type="password" id="login-password" name="password" autocomplete="current-password" required></div><div class="modal-actions"><button class="action-button" type="submit">Secure Login →</button></div></form><div class="callout">Public live rankings are visible without signing in. Event Managers can access only their assigned events.</div>`);}
async function checkSetup(){try{const s=await api('/api/setup/status');if(s.needs_setup){modal('🏆 First-Time Administrator Setup',`<div class="callout warning">The first-run Admin Setup Code is printed in the Windows backend console and saved to backend/bootstrap-code.txt. Keep it private.</div><form id="setup-form"><div class="field-group"><label class="field-label">Private Setup Code</label><input class="text-field" name="setup_code" required autocomplete="off"/></div><div class="field-group"><label class="field-label">Your Full Name</label><input class="text-field" name="name" required maxlength="120"/></div><div class="field-group"><label class="field-label">Admin Username</label><input class="text-field" name="username" required pattern="[A-Za-z0-9_.-]{3,40}"/></div><div class="field-group"><label class="field-label">Admin Password (10+ characters)</label><input class="text-field" type="password" name="password" required minlength="10"/></div><div class="modal-actions"><button type="submit" class="action-button">Create Admin</button></div></form>`);}}catch{}}
function rootModal(parentId){const p=getEvent(parentId);const parent=p?.name||'General Events';const options=[['sports','SPORTS GAMES (6–1 pts)'],['saludo','SALUDO CONTEST (20–5 pts)'],['emblem','BEST EMBLEM '+(state.public?.branding?.year||2026)+' (20–5 pts)'],['singing','SINGING DUET (6–1 pts)']];modal(p?'➕ Add Sub-event':'➕ Add General Event',`<p class="muted small">${p?'Under: '+esc(parent):'Create a new top-level category'}</p><form id="event-form"><input type="hidden" name="parent_id" value="${p?p.id:''}"><div class="field-group"><label class="field-label">Event / Sub-event Name</label><input name="name" class="text-field" maxlength="100" required placeholder="e.g., 200m Dash – Girls"></div>${!p?`<div class="field-group"><label class="field-label">Official Scoring Rule</label><select name="rule" class="select-field">${options.map(o=>`<option value="${o[0]}">${o[1]}</option>`).join('')}</select></div>`:`<div class="callout">Automatically inherits the <b>${esc(parent)}</b> official scoring rule.</div>`}<div class="modal-actions">${btn('Cancel','close-modal','','secondary')}<button type="submit" class="action-button">Add Event</button></div></form>`);}
function editEventModal(id){const e=getEvent(id);if(!e)return;modal('✎ Rename Event',`<form id="edit-event-form" data-id="${id}"><div class="field-group"><label class="field-label">Event Name</label><input name="name" class="text-field" maxlength="100" required value="${esc(e.name)}"></div><div class="modal-actions">${btn('Cancel','close-modal','','secondary')}<button type="submit" class="action-button">Save</button></div></form>`);}
function deleteEventModal(id){const e=getEvent(id);if(!e)return;modal('🗑 Delete / Archive Event',`<p>Are you sure you want to remove <strong>${esc(e.name)}</strong> and its sub-events?</p><div class="callout warning">If existing tally records are attached, this event and its children will be archived (not permanently destroyed), and associated official points will be removed from active standings.</div><div class="modal-actions">${btn('Cancel','close-modal','','secondary')}${btn('Confirm Remove','confirm-delete',id,'danger')}</div>`);}
async function encodeModal(id){const e=getEvent(id);if(!e)return;const response=await api(`/api/events/${id}/result`);const existing=response.result||{},readOnly=['submitted','approved'].includes(existing.status);state.currentEvent=id;const rule=response.rule;const options=[['','Choose placement…'],...rule.placements.map(([key,label,points])=>[key,`${label} (+${points})`])];const entries=existing.entries||{};
modal('🏅 Encode Final Placements',`<div class="callout"><strong>${esc(eventLabel(e))}</strong><br><span class="tiny">${esc(e.path||trail(e))}</span><br>Official scoring: ${esc(rule.label)}</div>${badge(existing.status||'draft')}${existing.comment?`<div class="callout warning">Admin note: ${esc(existing.comment)}</div>`:''}<form id="placements-form" data-id="${id}" data-revision="${Number(existing.revision)||0}"><div class="entry-grid">${grades.map(g=>`<div class="entry-card"><div class="grade-label">${logo(g)} Grade ${g}</div><label class="field-label" for="placement-${g}">Final Placement</label><select id="placement-${g}" class="select-field placement-select" name="g${g}" ${readOnly?'disabled':''} required>${options.map(([key,title])=>`<option value="${esc(key)}" ${entries[g]===key?'selected':''}>${esc(title)}</option>`).join('')}</select></div>`).join('')}</div><div class="score-preview" id="score-preview"></div><div id="placement-error"></div><div class="modal-actions">${btn('Close','close-modal','','secondary')}${!readOnly?'<button class="action-button secondary" name="intent" value="save" type="submit">Save Draft</button><button class="action-button" name="intent" value="submit" type="submit">Submit for Approval →</button>':''}</div></form>${readOnly?`<div class="callout warning">Official results are read-only. ${existing.status==='approved'?'Need a correction? Submit a documented request for Admin review.':'Awaiting verification.'}</div>${existing.status==='approved'?btn('✎ Request Official Correction','request-correction',id,'secondary'):''}`:'<p class="input-help">Every grade must have a placement. Champion and runner-up ranks must not be duplicated. Participation / No Participation may be assigned to multiple grades.</p>'}`,true);updatePreview();}
async function correctionModal(id){
 const e=getEvent(id);if(!e)return;
 const out=await api('/api/events/'+id+'/result'),current=out.result,request=out.correction;
 if(current?.status!=='approved')throw Error('Corrections require approved results');
 if(request?.status==='pending')throw Error('An official correction request is already pending Admin review');
 const options=out.rule.placements.map(([key,label,pts])=>`<option value="${esc(key)}">${esc(label)} (+${pts})</option>`).join('');
 modal('✎ Request Official Correction',`<div class="callout"><b>${esc(eventLabel(e))}</b><br>Existing published points will remain unchanged until Admin approval.</div><form id="correction-form" data-id="${id}" data-revision="${Number(current.revision)}"><div class="entry-grid">${grades.map(g=>`<div class="entry-card"><div class="grade-label">${logo(g)} Grade ${g}</div><label class="field-label">Proposed placement</label><select name="g${g}" class="select-field correction-select" required>${options.replace(`value="${esc(current.entries[g])}"`,`value="${esc(current.entries[g])}" selected`)}</select></div>`).join('')}</div><div id="correction-preview" class="score-preview"></div><div id="correction-error"></div><div class="field-group" style="margin-top:14px"><label class="field-label">Reason for override (required, minimum 15 characters)</label><textarea class="text-field" name="reason" minlength="15" maxlength="1200" rows="4" required placeholder="Describe what was incorrect and the basis for the corrected official placement."></textarea></div><div class="modal-actions">${btn('Cancel','close-modal','','secondary')}<button type="submit" class="action-button">Submit Correction Request</button></div></form>`,true);
 updateCorrectionPreview();
}
function updateCorrectionPreview(){const form=$('correction-form');if(!form)return;const e=getEvent(Number(form.dataset.id)),rules=RULES_CACHE[e?.rule]||[];const used=new Set();let error='';const points=grades.map(g=>{const entry=form.elements['g'+g]?.value;const row=rules.find(r=>r[0]===entry);if(!row)return {g,score:null};if(!['participation','none'].includes(entry)){if(used.has(entry))error='Duplicate ranked placement: '+row[1];used.add(entry);}return {g,score:row[2]};});$('correction-preview').innerHTML=points.map(({g,score})=>`<div class="preview-item">Grade ${g}<strong>${score===null?'—':'+'+score}</strong></div>`).join('');$('correction-error').innerHTML=error?`<div class="callout error">${esc(error)}</div>`:'';}
function correctionReviewModal(id){const r=state.corrections.find(x=>x.id===Number(id));if(!r)return;const rule=RULES_CACHE[r.rule]||[];const label=k=>rule.find(x=>x[0]===k);const rows=grades.map(g=>{const before=label(r.original_entries[g]),after=label(r.proposed_entries[g]);return `<tr><td>Grade ${g}</td><td>${esc(before?.[1]||'—')} (+${before?.[2]??'—'})</td><td>${esc(after?.[1]||'—')} (+${after?.[2]??'—'})</td><td>${(after?.[2]||0)-(before?.[2]||0)>0?'+':''}${(after?.[2]||0)-(before?.[2]||0)}</td></tr>`;}).join('');modal('⚖ Review Correction — '+r.event_name,`<p class="small">Manager: <b>${esc(r.manager_name)}</b></p><div class="callout warning"><b>Reason:</b> ${esc(r.reason)}</div><div class="table-wrap"><table class="report-table"><tr><th>Grade</th><th>Official</th><th>Proposed</th><th>Δ Points</th></tr>${rows}</table></div><p class="muted small">Current official points remain published until approved. The before-and-after changes are saved to the audit trail.</p><div class="field-group"><label class="field-label">Review note (mandatory if rejected)</label><textarea id="correction-review-note" class="text-field" maxlength="800" rows="3" placeholder="Reason for rejection or optional approval note"></textarea></div><div class="modal-actions">${btn('Cancel','close-modal','','secondary')}${btn('Reject Request','do-correction-reject',id,'danger')}${btn('Approve Replacement','do-correction-approve',id)}</div>`,true);}
function resetModal(){modal('⚠ Reset Operational Results',`<div class="callout warning">This clears ALL practice draft, submitted and approved results, plus pending correction requests. Grade standings return to zero. Accounts, sport structures, assignments, scoring rules and logos are preserved. A complete pre-reset backup is saved automatically.</div><div class="field-group"><label class="field-label">Type RESET PANAGSANGKA</label><input id="reset-confirmation" class="text-field" autocomplete="off" placeholder="RESET PANAGSANGKA"></div><div class="modal-actions">${btn('Cancel','close-modal','','secondary')}${btn('Confirm Operational Reset','do-reset','','danger')}</div>`);}
async function restoreModal(){const rows=(await api('/api/admin/backups')).backups;modal('♻ Restore Database Backup',`<div class="callout warning">Restoring will replace current database records with the selected local backup. All connected accounts will be logged out. The system automatically creates a pre-restore safety backup first.</div><div class="field-group"><label class="field-label">Available backend/backups snapshots</label><select id="restore-filename" class="select-field">${rows.map(x=>`<option value="${esc(x.filename)}">${esc(x.filename)} (${(x.size/1024).toFixed(0)} KB${x.has_assets?', with logos':''})</option>`).join('')}</select></div><div class="field-group"><label class="field-label">Type RESTORE PANAGSANGKA</label><input id="restore-confirmation" class="text-field" placeholder="RESTORE PANAGSANGKA" autocomplete="off"></div><div class="modal-actions">${btn('Cancel','close-modal','','secondary')}${rows.length?btn('⬇ Download Selected','download-backup','','secondary')+btn('Restore Snapshot','do-restore','','danger'):'<span class="muted small">No local backups exist. Create a Backup first.</span>'}</div>`);}
function updatePreview(){const form=$('placements-form');if(!form)return;const e=getEvent(state.currentEvent),r=e?RULES_CACHE[e.rule]:null;if(!r)return;let points={},used=new Set(),err='';for(const g of grades){const rank=form.elements['g'+g]?.value;const row=r.find(x=>x[0]===rank);points[g]=row?row[2]:null;if(row&&!['participation','none'].includes(rank)){if(used.has(rank))err='Duplicate placement detected: '+row[1];used.add(rank);}}$('score-preview').innerHTML=grades.map(g=>`<div class="preview-item">Grade ${g}<strong>${points[g]===null?'—':'+'+points[g]}</strong></div>`).join('');$('placement-error').innerHTML=err?`<p class="callout error">${esc(err)}</p>`:'';}
const RULES_CACHE={sports:[['champion','Champion',6],['runner1','1st Runner-up',5],['runner2','2nd Runner-up',4],['runner3','3rd Runner-up',3],['runner4','4th Runner-up',2],['runner5','5th Runner-up',1],['none','No Participation',0]],singing:[['champion','Champion',6],['runner1','1st Runner-up',5],['runner2','2nd Runner-up',4],['runner3','3rd Runner-up',3],['runner4','4th Runner-up',2],['runner5','5th Runner-up',1],['none','No Participation',0]],saludo:[['champion','Champion',20],['runner1','1st Runner-up',15],['runner2','2nd Runner-up',10],['participation','Participation',5],['none','No Participation',0]],emblem:[['champion','Mr. and Ms. Sports',20],['runner1','1st Runner-up',15],['runner2','2nd Runner-up',10],['participation','Participation',5],['none','No Participation',0]]};
function managerAddModal(){modal('👤 Create Manager Account',`<form id="new-user-form"><div class="field-group"><label class="field-label">Full Name</label><input class="text-field" name="name" required maxlength="120"></div><div class="field-group"><label class="field-label">Username (letters/numbers)</label><input class="text-field" name="username" pattern="[A-Za-z0-9_.-]{3,40}" required></div><div class="field-group"><label class="field-label">Initial Password (minimum 10 chars)</label><input class="text-field" name="password" type="password" minlength="10" required></div><div class="callout">Manager will have zero access until an Admin explicitly assigns events.</div><div class="modal-actions"><button type="submit" class="action-button">Create Manager</button></div></form>`);}
function assignmentsModal(userId){
  const u=state.users.find(x=>x.id===Number(userId));if(!u)return;
  // Build the canonical options from the current hierarchy. Never show leaf
  // sub-events as independent checkboxes under a main sport.
  const roots=state.events.filter(e=>e.parent_id===null);
  const sportsRoot=roots.find(e=>e.rule==='sports'&&e.name.trim().toUpperCase()==='SPORTS GAMES');
  const mains=sportsRoot?state.events.filter(e=>e.parent_id===sportsRoot.id):[];
  const general=roots.filter(e=>e.id!==sportsRoot?.id);
  const groups=[['🏅 MAIN SPORTS',mains],['🎭 OTHER OFFICIAL CONTESTS',general]];
  function legacyIncludes(selected){
    // Existing old-format assignments to a parent or child are displayed as
    // their corresponding main-sport checkbox, so resaving normalizes them.
    return u.assignments.some(id=>{
      if(id===selected.id)return true;
      let n=getEvent(id),limit=0;
      while(n?.parent_id&&limit++<60){n=getEvent(n.parent_id);if(n?.id===selected.id)return true;}
      if(sportsRoot&&u.assignments.includes(sportsRoot.id)&&selected.parent_id===sportsRoot.id)return true;
      return false;
    });
  }
  const html=groups.map(([label,items])=>items.length?`<div class="assignment-group"><div class="assignment-heading">${esc(label)} <span class="assignment-count">${items.length} options</span></div>${items.map(e=>`<label class="assignment-option"><input type="checkbox" name="event" value="${e.id}" ${legacyIncludes(e)?'checked':''}><span class="assignment-option-text"><strong>${esc(e.name)}</strong><small>${e.parent_id===sportsRoot?.id?'Automatically includes every current and future '+esc(e.name)+' sub-event':'Includes its sub-events, if any'}</small></span></label>`).join('')}</div>`:'').join('');
  modal('🔒 Assign Main Sports — '+esc(u.name),`<div class="callout">Select <b>main sports only</b> (Athletics, Basketball, Chess, etc.). Their sub-events are included automatically. The SPORTS GAMES category is not assignable; sub-events never appear as individual checkboxes.</div><form id="assign-form" data-id="${userId}"><div class="assignment-scroll">${html||'<p>No main sports are configured yet.</p>'}</div><div class="modal-actions">${btn('Cancel','close-modal','','secondary')}<button class="action-button" type="submit">Save Assignments</button></div></form>`,true);
}
function editUserModal(userId){const u=state.users.find(x=>x.id===Number(userId));if(!u)return;modal('Edit Account — '+u.name,`<form id="edit-user-form" data-id="${u.id}"><div class="field-group"><label class="field-label">Full Name</label><input class="text-field" name="name" value="${esc(u.name)}" required maxlength="120"></div><div class="field-group"><label class="field-label">New Password (leave blank to preserve)</label><input class="text-field" name="password" type="password" autocomplete="new-password" minlength="10"></div>${u.id!==state.user?.id?`<div class="field-group"><label><input type="checkbox" name="active" ${u.active?'checked':''}> Account Active</label></div>`:''}<div class="modal-actions"><button class="action-button" type="submit">Save Account</button></div></form>`);}
async function reviewModal(id){const record=state.results.find(x=>x.event_id===Number(id));if(!record)return;const rows=grades.map(g=>`<tr><td>Grade ${g}</td><td>${esc(record.entries[g])}</td><td>+${RULES_CACHE[record.rule]?.find(a=>a[0]===record.entries[g])?.[2]||0}</td></tr>`).join('');modal('🔎 Review — '+record.event_name,`<table class="report-table"><tr><th>Grade</th><th>Placement</th><th>Points</th></tr>${rows}</table><div class="modal-actions">${btn('Close','close-modal','','secondary')}${btn('↩ Return','return',id,'danger')}${btn('✓ Approve','approve',id)}</div>`);}
function decisionModal(id,decision){const r=state.results.find(x=>x.event_id===Number(id));if(!r)return;if(decision==='approve'){modal('✓ Confirm Official Approval',`<p>Approve final placements for <strong>${esc(r.event_name)}</strong>?</p><div class="callout">The grade-level overall leaderboard will update immediately for everyone.</div><div class="modal-actions">${btn('Cancel','close-modal','','secondary')}${btn('Approve Now','do-approve',id)}</div>`);return;}
modal('↩ Return for Correction',`<p><strong>${esc(r.event_name)}</strong> will become editable by its assigned Event Managers.</p><div class="field-group"><label class="field-label">Reason for correction</label><textarea id="decision-comment" class="text-field" rows="3" placeholder="Required reason, e.g. incorrect runners-up"></textarea></div><div class="modal-actions">${btn('Cancel','close-modal','','secondary')}${btn('Confirm Return','do-return',id,'danger')}</div>`);}
async function loadAll(silent=false){if(state.refreshing)return;state.refreshing=true;try{state.public=await api('/api/public');try{state.history=await api('/api/history');if(!state.historySelected)state.historySelected=state.history.active_year;if(state.page==='history'&&Number(state.historySelected)!==Number(state.history.active_year))state.historyDetail=await api('/api/history/'+state.historySelected);}catch{}if(state.token){try{const m=await api('/api/me');state.user=m.user;state.events=(await api('/api/events')).events;if(state.user.role==='admin'){const [users,results,corrections,judging]=await Promise.all([api('/api/admin/users'),api('/api/admin/results'),api('/api/admin/corrections'),api('/api/admin/judging')]);state.users=users.users;state.results=results.results;state.corrections=corrections.requests;state.judgingAdmin=judging;state.judgeEvents=[];}else if(state.user.role==='judge'){state.judgeEvents=(await api('/api/judging/my')).events;state.judgingAdmin=null;state.users=[];state.results=[];state.corrections=[];if(!['judging-my','ranking'].includes(state.page))state.page='judging-my';}else{state.judgingAdmin=null;state.judgeEvents=[];state.users=[];state.results=[];state.corrections=[];if(state.page==='dashboard')state.page='my';}}catch(err){if(state.user===null){state.events=[];state.users=[];state.results=[];state.corrections=[];state.page='dashboard';}if(!silent)flash(err.message,'bad');}}else{state.user=null;state.events=[];state.users=[];state.results=[];state.corrections=[];}render();}catch(err){if(!silent)flash(err.message,'bad');state.online=false;onlineStatus();if(!state.initialized)render();}finally{state.initialized=true;state.refreshing=false;}}
function goPage(page){if(!navItems().some(x=>x[0]===page))return;closeModal();state.page=page;render();window.scrollTo({top:0,behavior:'instant'});}
async function handleClick(action,id){try{switch(action){case 'page':goPage(id);break;case 'more':modal('Navigation',`<div class="more-menu">${navItems().slice(4).map(([key,name])=>btn(ICONS[key]+' '+name,'page',key,'secondary')).join('')}</div>`);break;case 'close-modal':closeModal();break;case 'profile':if(state.user)modal('Account — '+state.user.name,`<div class="callout">Signed in as <b>${esc(state.user.username)}</b> (${esc(state.user.role)})</div><div class="modal-actions">${btn('Close','close-modal','','secondary')}${btn('Sign Out','logout','','danger')}</div>`);else loginModal();break;case 'logout':await POST('/api/logout',{}).catch(()=>{});state.token='';state.user=null;localStorage.removeItem('panag_auth');if(state.socket){state.socket.disconnect();state.socket.auth={token:''};state.socket.connect();}closeModal();state.page='dashboard';await loadAll();flash('Signed out');break;case 'toggle-tree':state.expanded.has(Number(id))?state.expanded.delete(Number(id)):state.expanded.add(Number(id));render();break;case 'new-root':rootModal(null);break;case 'new-child':rootModal(Number(id));break;case 'edit-event':editEventModal(id);break;case 'delete-event':deleteEventModal(id);break;case 'confirm-delete':{const out=await api('/api/admin/events/'+id,{method:'DELETE'});closeModal();await loadAll(true);flash(out.archived?'Event archived safely':'Event deleted');break;}case 'encode':await encodeModal(id);break;case 'request-correction':await correctionModal(id);break;case 'review-correction':correctionReviewModal(id);break;case 'do-correction-approve':case 'do-correction-reject':{const decision=action==='do-correction-approve'?'approve':'reject',comment=$('correction-review-note')?.value||'';await POST('/api/admin/corrections/'+id+'/decision',{decision,comment});closeModal();await loadAll(true);flash(decision==='approve'?'Official replacement approved — live standings updated':'Correction rejected with reason');break;}case 'add-user':managerAddModal();break;case 'assign':assignmentsModal(id);break;case 'edit-user':editUserModal(id);break;case 'approve':decisionModal(id,'approve');break;case 'return':decisionModal(id,'return');break;case 'do-approve':await POST('/api/admin/results/'+id+'/decision',{decision:'approve'});closeModal();await loadAll(true);flash('Results approved. Live standings updated.');break;case 'do-return':{const c=$('decision-comment')?.value||'';if(c.trim().length<3)throw Error('Enter a correction reason');await POST('/api/admin/results/'+id+'/decision',{decision:'return',comment:c});closeModal();await loadAll(true);flash('Results returned to manager');break;}case 'review':reviewModal(id);break;case 'save-school':{const name=$('school-name').value;await PATCH('/api/admin/settings',{school_name:name});await loadAll(true);flash('School identity saved');break;}case 'save-branding':{const payload={};for(const [key] of PanagSeasonsUI.fields){payload[key]=$('brand-'+key)?.value?.trim()||'';}await PATCH('/api/admin/branding',payload);await loadAll(true);flash('Event branding published across live devices');break;}
case 'finalize-season':{const year=state.history?.active_year||state.public?.branding?.year||2026;modal('🏁 Finalize '+year+' & Start New Season',PanagSeasonsUI.finalizeForm(year,esc,btn),true);break;}
case 'do-finalize':{const next=Number($('next-season-year')?.value),confirmation=$('finalize-confirm')?.value||'',reason=$('finalize-reason')?.value||'';const result=await POST('/api/admin/seasons/finalize',{new_year:next,confirmation,reason});closeModal();state.historySelected=result.active_year;state.historyDetail=null;await loadAll(true);goPage('history');flash('Season '+result.archived_year+' safely archived; '+result.active_year+' starts at zero. Backup: '+result.backup);break;}
case 'export-history':{const year=state.historySelected;if(!year||year===(state.history?.active_year))throw Error('Choose an archived year');const content=await api('/api/admin/history/'+year);const blob=new Blob([JSON.stringify(content,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PANAGSANGKA-'+year+'-Official-Archive.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);break;}
case 'print-history':window.print();break;
case 'print':window.print();break;case 'csv':{const r=await fetch(API+'/api/admin/export.csv',{headers:{Authorization:'Bearer '+state.token}});if(!r.ok)throw Error('CSV export failed');const blob=await r.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='PANAGSANGKA-'+(state.public?.branding?.year||2026)+'-Overall-Tally.csv';a.click();URL.revokeObjectURL(url);break;}case 'backup':{const r=await POST('/api/admin/backup',{});flash('Database + logos backed up on PC: '+r.filename);break;}
case 'open-reset':resetModal();break;
case 'do-reset':{const confirmation=$('reset-confirmation')?.value||'';const r=await POST('/api/admin/reset-operational',{confirmation});closeModal();await loadAll(true);flash('Practice results cleared. Safety backup: '+r.backup);break;}
case 'open-restore':await restoreModal();break;
case 'do-restore':{const filename=$('restore-filename')?.value||'',confirmation=$('restore-confirmation')?.value||'';await POST('/api/admin/restore',{filename,confirmation});closeModal();state.token='';state.user=null;localStorage.removeItem('panag_auth');state.page='dashboard';state.historySelected=null;state.historyDetail=null;if(state.socket){state.socket.disconnect();state.socket.auth={token:''};state.socket.connect();}await loadAll(true);flash('Backup restored. Please sign in again.');break;}
case 'download-backup':{const filename=$('restore-filename')?.value||'';if(!filename)throw Error('Choose a backup');const response=await fetch(API+'/api/admin/backups/'+encodeURIComponent(filename)+'/download',{headers:{Authorization:'Bearer '+state.token}});if(!response.ok)throw Error('Could not download backup');const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);flash('Database snapshot downloaded. Logo assets remain inside the PC backup folder.');break;}
}}catch(err){flash(err.message||String(err),'bad');}}
async function handleSubmit(form,submitter){const data=new FormData(form);try{switch(form.id){case 'login-form':{const s=await POST('/api/login',{username:data.get('username'),password:data.get('password')});state.token=s.token;state.user=s.user;if(state.socket){state.socket.disconnect();state.socket.auth={token:s.token};state.socket.connect();}localStorage.setItem('panag_auth',s.token);state.page=s.user.role==='admin'?'dashboard':s.user.role==='judge'?'judging-my':'my';closeModal();await loadAll();flash('Welcome, '+s.user.name);break;}case 'setup-form':await POST('/api/setup',Object.fromEntries(data.entries()));closeModal();flash('Admin account created. Please log in.');loginModal();break;case 'event-form':await POST('/api/admin/events',{name:data.get('name'),parent_id:data.get('parent_id')?Number(data.get('parent_id')):null,rule:data.get('rule')||undefined});closeModal();await loadAll(true);flash('Event added');break;case 'edit-event-form':await PATCH('/api/admin/events/'+form.dataset.id,{name:data.get('name')});closeModal();await loadAll(true);flash('Event renamed');break;case 'new-user-form':await POST('/api/admin/users',{name:data.get('name'),username:data.get('username'),password:data.get('password'),role:'manager'});closeModal();await loadAll(true);flash('Manager created. Assign events next.');break;case 'assign-form':{const ids=Array.from(form.querySelectorAll('input[name=event]:checked')).map(x=>Number(x.value));await PUT('/api/admin/users/'+form.dataset.id+'/assignments',{event_ids:ids});closeModal();await loadAll(true);flash('Event access updated');break;}case 'edit-user-form':{const obj={name:data.get('name')};if(data.get('password'))obj.password=data.get('password');if(form.elements.active)obj.active=data.get('active')==='on';await PATCH('/api/admin/users/'+form.dataset.id,obj);closeModal();await loadAll(true);flash('User account updated');break;}case 'correction-form':{const id=form.dataset.id,entries={};grades.forEach(g=>entries[g]=data.get('g'+g));const reason=String(data.get('reason')||'');await POST('/api/events/'+id+'/correction',{entries,reason,expected_revision:Number(form.dataset.revision)});closeModal();await loadAll(true);flash('Official correction requested. Published tally remains unchanged.');break;}
case 'placements-form':{const id=form.dataset.id;const entries={};grades.forEach(g=>entries[g]=data.get('g'+g));await PUT('/api/events/'+id+'/result',{entries,expected_revision:Number(form.dataset.revision)||0});if(submitter?.value==='submit')await POST('/api/events/'+id+'/submit',{expected_revision:(Number(form.dataset.revision)||0)+1});closeModal();await loadAll(true);flash(submitter?.value==='submit'?'Placements submitted for Admin verification':'Draft saved');break;}}}catch(err){flash(err.message||String(err),'bad');}}
async function uploadLogo(input){const file=input.files?.[0];if(!file)return;if(file.size>24*1024*1024){flash('File is larger than the 24MB upload limit.','bad');return;}flash('Optimizing and uploading logo…');const reader=new FileReader();reader.onload=async()=>{try{const r=await POST('/api/admin/logo',{type:input.dataset.upload,grade:input.dataset.upload==='grade'?Number(input.dataset.grade):undefined,data:reader.result});await loadAll(true);flash(`Logo optimized from ${Math.round(r.original_bytes/1024)} KB to ${Math.round(r.optimized_bytes/1024)} KB`);}catch(e){flash(e.message,'bad');}};reader.readAsDataURL(file);}
function realtime(){if(typeof window.io!=='function'){setTimeout(realtime,3500);return;}if(state.socket)return;const socket=window.io(API,{auth:{token:state.token},reconnection:true,reconnectionAttempts:Infinity,timeout:7000});state.socket=socket;socket.on('system:restored',()=>{state.token='';state.user=null;localStorage.removeItem('panag_auth');state.page='dashboard';refresh();flash('Database restored — please log in again.','bad');});socket.on('connect',()=>{state.online=true;onlineStatus();});socket.on('disconnect',()=>{state.online=false;onlineStatus();});let delay=null;const refresh=()=>{clearTimeout(delay);delay=setTimeout(()=>loadAll(true),250);};['leaderboard:updated','events:updated','results:updated','branding:updated','assignments:updated','corrections:updated','judging:updated','season:updated'].forEach(t=>socket.on(t,refresh));}
function initializeEvents(){document.addEventListener('click',e=>{if(e.target===$('modal-backdrop'))closeModal();const target=e.target.closest('[data-action]');if(target)handleClick(target.dataset.action,target.dataset.id||'');});$('profile-button').addEventListener('click',()=>handleClick('profile'));document.addEventListener('submit',e=>{if(e.target?.id&&/^(login-form|setup-form|event-form|edit-event-form|new-user-form|assign-form|edit-user-form|placements-form|correction-form)$/.test(e.target.id)){e.preventDefault();handleSubmit(e.target,e.submitter);}});document.addEventListener('change',async e=>{if(e.target.matches('[data-history-selector]')){const year=Number(e.target.value);state.historySelected=year;state.historyDetail=null;if(year!==Number(state.history?.active_year)){try{state.historyDetail=await api('/api/history/'+year);}catch(err){flash(err.message,'bad');}}render();}if(e.target.matches('.placement-select'))updatePreview();if(e.target.matches('.correction-select'))updateCorrectionPreview();if(e.target.matches('input[data-upload]'))uploadLogo(e.target);});document.addEventListener('input',e=>{if(e.target.id?.startsWith('brand-')){for(const [key] of PanagSeasonsUI.fields){const preview=$('brand-preview-'+({event_name:'title',subtitle:'subtitle',tagline:'tagline',banner_kicker:'kicker',banner_motto:'motto',banner_detail:'detail',sidebar_words:'keywords'}[key]||key));if(preview){const current=$('brand-'+key)?.value||'';preview.textContent=key==='event_name'?current+' '+(state.public?.branding?.year||2026):key==='sidebar_words'?current.replace(/\n/g,' · '):current;}}}});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});}
async function init(){initializeEvents();await loadAll();await checkSetup();realtime();setInterval(()=>loadAll(true),Number(CFG.POLL_FALLBACK_MS)||20000);if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});}
init();
})();
